entries[409946] = { ["name"] = "Maelstrom Weapon", ["text"] = "Gain the Maelstrom Weapon ability:\n\nWhen you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec." }
entries[409947] = { ["name"] = "Earth Shield", ["text"] = "Gain the Earth Shield ability:\n\nProtects the target with an earthen shield, reducing casting or channeling time lost when damaged by 30% and causing attacks to heal the shielded target for [source value]. This effect can only occur once every few seconds. 9 charges. Lasts 10 min. Earth Shield can only be placed on one target at a time.", ["unresolvedValues"] = true }
entries[409951] = { ["name"] = "Spirit of the Alpha", ["text"] = "Gain the Spirit of the Alpha ability:\n\nInfuses the target with the spirit of an alpha wolf, increasing all threat generated by the target by 45% for 30 min. Limit 1 target. If cast on a target other than self, the Shaman also gains Loyal Beta, increasing Physical damage done by 5% and reducing all threat generated by 30% for 30 min. A target cannot have both Spirit of the Alpha and Loyal Beta at the same time." }
entries[409952] = { ["name"] = "Lava Burst", ["text"] = "Gain the Lava Burst ability:\n\nYou hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage." }
entries[409953] = { ["name"] = "Lava Lash", ["text"] = "Gain the Lava Lash ability:\n\nYou charge your off-hand weapon with lava, instantly dealing 100% off-hand Weapon damage. Damage is increased by 100% if your off-hand weapon is enchanted with Flametongue." }
entries[409954] = { ["name"] = "Riptide", ["text"] = "Gain the Riptide ability:\n\nHeals a friendly target for 486 to 534, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%." }
entries[409955] = { ["name"] = "Way of Earth", ["text"] = "Gain the Way of Earth ability:\n\nWhile Rockbiter Weapon is active on your main hand weapon and you have a shield equipped, you deal 65% increased threat, gain 30% increased health, take 10% reduced damage, gain 6% reduced chance to be critically hit by melee attacks, and Earth Shock taunts targets to attack you and has a separate cooldown from other Shock spells but has its range reduced to melee range. However, the range of your Lightning Bolt, Chain Lightning, Chain Heal, Healing Wave, and Lava Burst spells is reduced by 20 yards." }
entries[409957] = { ["name"] = "Steady Shot", ["text"] = "Gain the Steady Shot ability:\n\nA steady shot that causes 100% ranged weapon damage." }
entries[409958] = { ["name"] = "Master Marksman", ["text"] = "Gain the Master Marksman ability:\n\nIncreases your critical strike chance by 5%, and reduces the Mana cost of all your Shot abilities by 25%." }
entries[409959] = { ["name"] = "Expose Weakness", ["text"] = "Gain the Expose Weakness ability:\n\nYour melee and ranged criticals increase your attack power by 40% of your current Agility for 7 sec." }
entries[409960] = { ["name"] = "Cobra Slayer", ["text"] = "Gain the Cobra Slayer ability:\n\nMongoose Bite now has a 10% chance to activate on each of your melee attacks, a 100% chance when an enemy dodges. This chance accumulates, with the chance rising by 10% from each subsequent attack if it does not reset. Mongoose Bite also deals additional damage equal to 45% of your Attack Power." }
entries[409961] = { ["name"] = "Dual Wield Specialization", ["text"] = "Gain the Dual Wield Specialist ability:\n\nIncreases the damage done by your offhand weapon by 60% and causes your Raptor Strike to strike with both weapons when you are dual-wielding." }
entries[409962] = { ["name"] = "Beast Mastery", ["text"] = "Gain the Beast Mastery ability:\n\nYour pet's damage and health are increased by 15%, and its Focus regeneration by 50%. In addition, your pet's Growl now also Taunts the target to attack it for 3 sec." }
entries[409963] = { ["name"] = "Summon Spirit" }
entries[409968] = { ["name"] = "Trap Launcher", ["text"] = "Gain the Trap Launcher ability:" }
entries[409974] = { ["name"] = "Kill Shot", ["text"] = "Gain the Kill Shot ability:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[409976] = { ["name"] = "Chimera Shot", ["text"] = "Gain the Chimera Shot ability:\n\nYou deal 135% weapon damage, refreshing the current Sting on your target and triggering an effect:\n\nSerpent Sting - Instantly deals 48% of the damage done by your Serpent Sting.\n\nViper Sting - Instantly restores mana to you equal to 60% of the total amount drained by your Viper Sting.\n\nScorpid Sting - Attempts to Disarm the target for 10 sec. This effect cannot occur more than once per 1 minute." }
entries[409979] = { ["name"] = "Lone Wolf", ["text"] = "Gain the Lone Wolf ability:\n\nYou deal 20% increased damage with all attacks while you do not have an active pet." }
entries[409988] = { ["name"] = "Force Player Cast Delayed Banish" }
entries[409999] = { ["name"] = "Engrave Gloves - Beacon of Light", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Beacon of Light rune:" }
entries[410001] = { ["name"] = "Engrave Gloves - Hand of Reckoning", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Hand of Reckoning rune:" }
entries[410002] = { ["name"] = "Engrave Gloves - Crusader Strike", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Crusader Strike rune:" }
entries[410005] = { ["name"] = "Engrave Pants - Aura Mastery", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Aura Mastery rune:" }
entries[410008] = { ["name"] = "Engrave Pants - Avenger's Shield", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Avenger's Shield rune:" }
entries[410010] = { ["name"] = "Engrave Pants - Hand of Sacrifice", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Hand of Sacrifice rune:\n\nCauses target party or raid member to transfer 30% of damage taken to the caster. Lasts 12 sec or until the caster has transferred 100% of their maximum health." }
entries[410011] = { ["name"] = "Engrave Pants - Inspiration Exemplar", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Inspiration Exemplar rune:\n\nYour inspiring presence periodically dispels Fear and Sleep effects on nearby party members." }
entries[410013] = { ["name"] = "Engrave Bracers - Hammer of the Righteous", ["text"] = "3 sec cast\nRequires Bracers\nEngrave your bracers with the Hammer of the Righteous rune:\n\nHammer the current target and up to 3 additional nearby targets, causing Holy damage to each equal to 3 times the damage per second of your main hand weapon. Cooldown shared with Crusader Strike." }
entries[410014] = { ["name"] = "Engrave Chest - Divine Storm", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest with the Divine Storm rune:\n\nAn instant weapon attack that causes 110% of weapon damage to up to 4 enemies within 8 yards. The Divine Storm heals up to 3 party or raid members totaling 25% of the damage caused." }
entries[410015] = { ["name"] = "Engrave Cloak - Divine Light", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Divine Light rune:\n\nHeals a friendly target for [source value] to [source value]. 50% of any excess healing on the target is converted into an absorption shield that lasts 15 sec. Multiple casts of Divine Light do not accumulate this shield.\n\nDivine Light benefits from all talents and effects that trigger from or modify Holy Light.", ["unresolvedValues"] = true }
entries[410021] = { ["name"] = "Engrave Chest - Wild Strikes", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Wild Strikes rune:\n\nWhile you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within 100 yards gain increased combat ferocity. Each melee hit has a 20% chance of granting the attacker an extra attack with 20% additional Attack Power. No effect if the target is already benefitting from Windfury Totem." }
entries[410023] = { ["name"] = "Engrave Pants - Savage Roar", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Savage Roar rune:\n\nRequires Cat Form\nFinishing move that increases Physical damage done by 30% while in Cat Form. Lasts longer per combo point:\n1 point : (14 + 0 ) seconds\n2 points: (19 + 0 ) seconds\n3 points: (24 + 0 ) seconds\n4 points: (29 + 0 ) seconds\n5 points: (34 + 0 ) seconds" }
entries[410025] = { ["name"] = "Engrave Gloves - Mangle", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Mangle rune:\n\nBite the target, dealing 100% normal damage plus 26 and generating a high amount of threat." }
entries[410027] = { ["name"] = "Engrave Boots - Survival Instincts", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Survival Instincts rune:\n\nWhen activated, this grants you 30% of your maximum health and increases all non-Physical healing you deal by 20% for 20 sec. After the effect expires, the health is lost. Useable in all forms except Moonkin Form.\n\nIn addition, you regenerate 3 rage every time you dodge while in Bear Form or Dire Bear Form, 10 energy while in Cat Form, or 1% of your maximum mana while in any other form." }
entries[410028] = { ["name"] = "Engrave Gloves - Wild Growth", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Wild Growth rune:\n\nHeals the target and their party for 336 over 7 sec. Party members must be within 43.5 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration." }
entries[410029] = { ["name"] = "Engrave Belt - Eclipse", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Eclipse rune:\n\nYour Wrath spell reduces the cast time of your next 2 Starfire spells by 0.03 sec. Stores up to 4 charges. Lasts 15 sec." }
entries[410033] = { ["name"] = "Engrave Pants - Lifebloom", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Lifebloom rune:\n\nReduces the global cooldown on your Rejuvenation and Lifebloom abilities by 0.5 sec and you gain the Lifebloom ability:\n\nHeals the target for [source value] over 7 sec. When Lifebloom completes its duration or is dispelled, the target instantly heals for [source value] and the Druid regains half the cost of the spell. This effect can stack up to 3 times on the same target.", ["unresolvedValues"] = true }
entries[410059] = { ["name"] = "Engrave Belt - Nourish", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Nourish rune:\n\nHeals a friendly target for [source value] to [source value]. Heals for an additional 20% if you have a Rejuvenation, Regrowth, Lifebloom, or Wild Growth effect active on the target. This spell benefits from and triggers all effects associated with Healing Touch or Regrowth.", ["unresolvedValues"] = true }
entries[410060] = { ["name"] = "Engrave Boots - Dreamstate", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Dreamstate rune:\n\nYour damaging non-periodic spell critical strikes grant you 50% of your mana regeneration while casting for 8 sec." }
entries[410061] = { ["name"] = "Engrave Chest - Fury of Stormrage", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Fury of Stormrage rune:\n\nReduces the mana cost of Wrath by 100% and each time you deal damage with Wrath you have a 12% chance for your next cast of Healing Touch within 15 sec to be instant and castable in any shapeshift form. Allows Wrath to be cast while in Tree of Life form." }
entries[410093] = { ["name"] = "Engrave Belt - Fire Nova", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Fire Nova rune:\n\nYour Fire Nova Totem spell is replaced with Fire Nova, which causes your current Fire totem to emit damage at its location." }
entries[410094] = { ["name"] = "Engrave Chest - Overload", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Overload rune:\n\nGives your Lightning Bolt and Chain Lightning spells a 30% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat." }
entries[410095] = { ["name"] = "Engrave Gloves - Lava Burst", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Lava Burst rune:\n\nYou hurl molten lava at the target, dealing 150 to 192 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage." }
entries[410096] = { ["name"] = "Engrave Chest - Dual Wield Specialization", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Dual Wield Specialization rune:\n\nIncreases your chance to hit with both spells and melee attacks by 5% while dual wielding, your Stormstrike ability now hits with both weapons while dual wielding, and increases the damage done by your offhand weapon by 60%." }
entries[410097] = { ["name"] = "Engrave Gloves - Water Shield", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Water Shield rune:\n\nThe caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min.\n\nOnly one Elemental Shield can be active on the Shaman at any one time." }
entries[410098] = { ["name"] = "Engrave Chest - Shield Mastery", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Shield Mastery rune:\n\nEach time you Block, you regenerate mana equal to 8% of your maximum mana and you gain Armor equal to 30% of your shield's armor value, stacking up to 5 times. You also always gain 10% increased chance to Block and 15% increased Block value.\n\nIn addition, each time you use a Shock ability, you gain 4 Spell Damage for each point of your defense skill beyond ( 60 * 5). Lasts 15 sec." }
entries[410099] = { ["name"] = "Engrave Pants - Ancestral Guidance", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Ancestral Guidance rune:\n\nFor the next 10 sec, 25% of your damage is converted to healing on up to 3 nearby party members, and 100% of your healing is converted to damage on your most recent Flame Shock target." }
entries[410100] = { ["name"] = "Engrave Belt - Maelstrom Weapon", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Maelstrom Weapon rune:\n\nWhen you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec." }
