entries[415105] = { ["name"] = "Power Surge", ["text"] = "Instant\nModifies Cast Time -99%:\nChain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Chain Lightning , Lava Burst , Lava Burst , Lava Burst , Lava Burst , Lava Burst , Lava Burst" }
