entries[415233] = { ["name"] = "Ghost Wolf", ["text"] = "100 Mana\n3 sec cast\nTurns the Shaman into a Ghost Wolf, increasing speed by 40% and decreasing all damage taken by 10%." }
entries[415236] = { ["name"] = "Healing Rain", ["text"] = "21% of base mana 40 yd range\n2 sec cast 10 sec cooldown\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.", ["unresolvedValues"] = true }
