entries[415320] = { ["name"] = "Flanking Strike", ["text"] = "1.5% of base mana Melee Range\nInstant 30 sec cooldown\nRequires Melee Weapon\nYou and your pet deal simultaneous instant 100% melee damage. Afterward, you deal 8% increased damage for 10 sec, stacking up to 3 times. Your pet's Basic attacks have a 50% chance to reset the cooldown on Flanking Strike." }
entries[415326] = { ["name"] = "Flanking Strike", ["text"] = "Melee Range\nInstant\nYou and your pet deal simultaneous instant 100% melee damage. Afterward, your Mongoose Bite and Raptor Strike deal 0% increased damage for until canceled, stacking up to 1 times. Raptor Strike has a 0% chance to reset the cooldown on Flanking Strike." }
entries[415327] = { ["name"] = "Flanking Strike" }
