entries[415352] = { ["name"] = "Melee Specialist", ["text"] = "Your Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike." }
entries[415358] = { ["name"] = "Raptor Fury", ["text"] = "Raptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect." }
entries[415362] = { ["name"] = "Raptor Fury", ["text"] = "Instant\nModifies Damage/Healing Done +16%:\nMongoose Bite , Mongoose Bite , Mongoose Bite , Mongoose Bite , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike , Raptor Strike" }
entries[415370] = { ["name"] = "Lone Wolf", ["text"] = "You deal 20% increased damage with all attacks while you do not have an active pet." }
entries[415372] = { ["name"] = "Lone Wolf" }
entries[415399] = { ["name"] = "Sniper Training", ["text"] = "When you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%." }
entries[415401] = { ["name"] = "Sniper's Aim", ["text"] = "Instant\nModifies Critical Strike Chance +3:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Scatter Shot , Summon Hawk , Summon Hawk , Summon Hawk , Summon Hawk , Tranquilizing Shot" }
entries[415405] = { ["name"] = "Rapid Killing", ["text"] = "Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." }
entries[415407] = { ["name"] = "Rapid Killing", ["text"] = "Instant\nIncreases the damage of your next Shot ability by 20%." }
entries[415413] = { ["name"] = "Lock and Load", ["text"] = "Each time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown." }
entries[415414] = { ["name"] = "Lock and Load", ["text"] = "Instant\nModifies Cooldown -99%:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Chimera Shot , Chimera Shot - Serpent , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Tranquilizing Shot\n\nModifies Power Cost -99%:\nAimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Aimed Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Arcane Shot , Chimera Shot , Chimera Shot - Serpent , Concussive Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Distracting Shot , Multi-Shot , Tranquilizing Shot" }
entries[415423] = { ["name"] = "Aspect of the Viper", ["text"] = "Instant\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time." }
entries[415424] = { ["name"] = "Aspect of the Viper" }
entries[415428] = { ["name"] = "Catlike Reflexes", ["text"] = "Increases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%." }
entries[415429] = { ["name"] = "Hunter Pet Scaling", ["text"] = "(2s cooldown)" }
entries[415431] = { ["name"] = "Avoidance" }
entries[415449] = { ["name"] = "Waist Rune Ability", ["text"] = "Instant\nEquip a Waist slot item with a Rune engraved to activate an ability in this slot." }
entries[415450] = { ["name"] = "Feet Rune Ability", ["text"] = "Instant\nEquip a Feet slot item with a Rune engraved to activate an ability in this slot." }
entries[415452] = { ["name"] = "Improved Swipe", ["text"] = "Gain the Improved Swipe ability:\n\nWhile in Cat Form, your Swipe ability becomes Swipe (Cat), and while in Bear Form, your Swipe ability strikes up to 7 additional enemies.\n\nSwipe (Cat)\n\nSwipe nearby enemies, inflicting 250% weapon damage and generating 1 combo point on your current target." }
entries[415457] = { ["name"] = "Fan of Knives", ["text"] = "Gain the Fan of Knives ability:\n\nInstantly throw both weapons at all targets within 8 yards, causing 75% weapon damage with daggers, and 50% weapon damage with all other weapons." }
entries[415459] = { ["name"] = "Spell Power", ["text"] = "Gain the Spell Power ability:\n\nIncreases critical strike damage bonus of all spells by 50%." }
entries[415460] = { ["name"] = "Burnout", ["text"] = "Gain the Burnout ability:\n\nIncreases your spell critical strike chance with all spells by 15%, but your non-periodic spell critical strikes now have an additional mana cost of 1% of your base mana." }
entries[415467] = { ["name"] = "Mass Regeneration", ["text"] = "Gain the Mass Regeneration ability:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 80% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.", ["unresolvedValues"] = true }
entries[415481] = { ["name"] = "Pain and Suffering", ["text"] = "Gain the Pain and Suffering ability:\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed." }
entries[415596] = { ["name"] = "Shield Mastery", ["text"] = "Gain the Shield Mastery ability:" }
entries[415598] = { ["name"] = "Gladiator Stance", ["text"] = "Gain the Gladiator Stance ability:\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances." }
entries[415599] = { ["name"] = "Single-Minded Fury", ["text"] = "Gain the Single-Minded Fury ability:\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 3% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target." }
entries[415604] = { ["name"] = "Everlasting Affliction", ["text"] = "Gain the Everlasting Affliction ability:\n\nEach time your Drain Life, Drain Soul, or Shadowbolt spell deals damage, your Corruption on the target is refreshed to its maximum duration." }
entries[415605] = { ["name"] = "Demonic Tactics", ["text"] = "Gain the Demonic Tactics ability:\n\nIncreases the critical strike chance of all attacks for you and your summoned Demon by 10% while the Demon is active." }
entries[415703] = { ["name"] = "Sacred Shield", ["text"] = "Gain the Sacred Shield ability:\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [source value] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.", ["unresolvedValues"] = true }
entries[415706] = { ["name"] = "The Art of War", ["text"] = "Gain the The Art of War ability:\n\nIncreases all Holy damage you deal by 10%, and your melee and spell critical strikes reduce the remaining cooldown on your Exorcism spell by 2 sec." }
entries[415709] = { ["name"] = "Survival of the Fittest", ["text"] = "Gain the Survival of the Fittest ability:\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form." }
entries[415712] = { ["name"] = "Power Surge", ["text"] = "Gain the Power Surge ability:\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect." }
entries[415713] = { ["name"] = "Mental Dexterity", ["text"] = "Gain the Mental Dexterity ability:\n\nIncreases your Attack Power by an amount equal to 100% of your Intellect." }
entries[415714] = { ["name"] = "Healing Rain", ["text"] = "Gain the Healing Rain ability:\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.", ["unresolvedValues"] = true }
entries[415717] = { ["name"] = "Catlike Reflexes", ["text"] = "Gain the Catlike Reflexes ability:\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%." }
entries[415718] = { ["name"] = "Aspect of the Viper", ["text"] = "Gain the Aspect of the Viper ability:\n\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time." }
entries[415719] = { ["name"] = "Lock and Load", ["text"] = "Gain the Lock and Load ability:\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown." }
entries[415720] = { ["name"] = "Kill Shot", ["text"] = "Gain the Kill Shot ability:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[415723] = { ["name"] = "Melee Specialist", ["text"] = "Gain the Melee Specialist ability:\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike." }
entries[415725] = { ["name"] = "Waylay", ["text"] = "Gain the Waylay ability:\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec." }
entries[415729] = { ["name"] = "Enlightenment", ["text"] = "Gain the Enlightenment ability:\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting." }
entries[415734] = { ["name"] = "Spellfrost Bolt", ["text"] = "Gain the Spellfrost Bolt ability:\n\nLaunches a bolt of spellfrost at the enemy, causing [source value] to [source value] Spellfrost damage and slowing movement speed by 40% for 9 sec. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage.", ["unresolvedValues"] = true }
entries[415737] = { ["name"] = "Serendipity", ["text"] = "Gain the Serendipity ability:\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times." }
entries[415738] = { ["name"] = "Mind Sear", ["text"] = "Gain the Mind Sear ability:\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [source value] to [source value] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target.", ["unresolvedValues"] = true }
entries[415739] = { ["name"] = "Strength of Soul", ["text"] = "Lesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal." }
entries[415740] = { ["name"] = "Strength of Soul", ["text"] = "Gain the Strength of Soul ability:\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal." }
entries[415743] = { ["name"] = "Blood Surge", ["text"] = "Gain the Blood Surge ability:\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage." }
entries[415744] = { ["name"] = "Precise Timing", ["text"] = "Gain the Precision Timing ability:\n\nSlam is now instant but has a 6 sec cooldown." }
entries[415745] = { ["name"] = "Focused Rage", ["text"] = "Gain the Focused Rage ability:\n\nReduces the Rage cost of your offensive abilities by 3." }
entries[415749] = { ["name"] = "Demonic Knowledge", ["text"] = "Gain the Demonic Knowledge ability:\n\nIncreases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." }
entries[415750] = { ["name"] = "Incinerate", ["text"] = "Gain the Incinerate ability:\n\nDeals 100 to 114 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate." }
entries[415751] = { ["name"] = "Dance of the Wicked", ["text"] = "Gain the Dance of the Wicked ability:\n\nYou and your demon pet gain dodge chance equal to 100% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana." }
entries[415755] = { ["name"] = "Guarded by the Light", ["text"] = "Gain the Guarded by the Light ability:\n\nYou gain 5% of your maximum mana every 3 sec for 15 sec after Blocking a melee attack. This effect is cancelled by casting Flash of Light, Holy Light, or Holy Shock." }
entries[415756] = { ["name"] = "Aura Mastery", ["text"] = "Gain the Aura Mastery ability:" }
entries[415759] = { ["name"] = "Skull Bash", ["text"] = "Gain the Skull Bash ability:\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge." }
entries[415760] = { ["name"] = "Lacerate", ["text"] = "Gain the Lacerate ability:\n\nLacerates the enemy target, making them bleed for 50 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target." }
entries[415761] = { ["name"] = "Living Seed", ["text"] = "Gain the Living Seed ability:\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec." }
entries[415762] = { ["name"] = "Elune's Fires", ["text"] = "Gain the Elune's Fires ability:\n\nSome of your spells and abilities extend the duration of your damage and healing over time effects on their target:\n\nStarfire extends Moonfire by 6 sec.\nWrath extends Sunfire by 3 sec.\nRegrowth extends Rejuvenation by 6 sec.\nShred extends Rip by 2 sec.\n\nEach effect can only be extended up to its initial duration." }
entries[415768] = { ["name"] = "Burn", ["text"] = "Gain the Burn ability:\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect." }
entries[415813] = { ["name"] = "Greater Ghost Wolf", ["text"] = "Your Ghost Wolf ability can now be used indoors, and reduces all damage you take by 10% while active." }
entries[415816] = { ["name"] = "Wyvern Strike", ["text"] = "Gain the Wyvern Strike ability:\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\nWyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook." }
entries[415817] = { ["name"] = "Rapid Killing", ["text"] = "Gain the Rapid Killing ability:\n\nReduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." }
entries[415818] = { ["name"] = "Sniper Training", ["text"] = "Gain the Sniper Training ability:\n\nWhen you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%." }
entries[415822] = { ["name"] = "Raptor Fury", ["text"] = "Gain the Raptor Fury ability:\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect." }
entries[415918] = { ["name"] = "Engrave Cloak - Crimson Tempest", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Crimson Tempest rune:\n\nFinishing move that slashes all enemies within 8 yards, causing victims to Bleed over time. Lasts longer and deals more damage per combo point.\n\n1 point : (Attack Power * 0.30) damage over 4 sec.\n2 points: (Attack Power * 0.45) damage over 6 sec.\n3 points: (Attack Power * 0.60) damage over 8 sec.\n4 points: (Attack Power * 0.75) damage over 10 sec.\n5 points: (Attack Power * 0.90) damage over 12 sec.\n\nCrimson Tempest benefits from all talents and effects that trigger from or modify Rupture." }
entries[415922] = { ["name"] = "Engrave Cloak - Blunderbuss", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Blunderbuss rune:\n\nFire a musket blast at up to 4 enemies in a cone in front of you for [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 192 / 100 + 48 / 100 * Attack Power] to [(5.741530 - 0.255683 * 60 + 0.032656 * 60 * 60) * 288 / 100 + 48 / 100 * Attack Power] Physical damage." }
entries[415926] = { ["name"] = "Engrave Boots - Waylay", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Waylay rune:\n\nYour Ambush and Backstab hits unbalance your target, increasing the time between their melee attacks by 10%, and reducing movement speed by 50% for 8 sec." }
entries[415934] = { ["name"] = "Engrave Boots - Spell Power", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Spell Power rune:\n\nIncreases critical strike damage bonus of all spells by 50%." }
entries[415936] = { ["name"] = "Engrave Gloves - Living Bomb", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Living Bomb rune:\n\nThe target becomes a Living Bomb, taking [source value] Fire damage over 12 sec. After 12 sec or when the spell is dispelled, the target explodes dealing [source value] Fire damage to all enemies within 10 yards.\n\nLiving Bomb benefits from all talents and effects that trigger from or modify Scorch.", ["unresolvedValues"] = true }
entries[415939] = { ["name"] = "Engrave Pants - Mass Regeneration", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Mass Regeneration rune:\n\nHeals all of target player's party members within 43.5 yards of target player for [source value] health over 3 sec and applies Temporal Beacon to each target for 15 sec.\n\nTemporal Beacon\n\nRecords the subject's space-time position. 80% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by 50% on self, and also reduced by 80% when damage is done by Arcane spells that damage multiple targets.", ["unresolvedValues"] = true }
entries[415942] = { ["name"] = "Engrave Chest - Enlightenment", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Enlightenment rune:\n\nYou deal 10% more damage while you have more than 70% mana. While below 30% mana 10% of your mana regeneration continues while casting." }
entries[415948] = { ["name"] = "Engrave Belt - Spellfrost Bolt", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Spellfrost Bolt rune:\n\nLaunches a bolt of spellfrost at the enemy, causing [source value] to [source value] Spellfrost damage and slowing movement speed by 40% for 9 sec. This spell will be checked against the lower of the target's Frost and Arcane resists and counts as both Frost and Arcane damage.", ["unresolvedValues"] = true }
entries[415988] = { ["name"] = "Vahi Bonesplitter - Trade Centaur Head For Rune Fragment" }
entries[415991] = { ["name"] = "Engrave Helm - Pain and Suffering", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Pain and Suffering rune:\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed." }
entries[415995] = { ["name"] = "Engrave Chest - Serendipity", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Serendipity rune:\n\nHealing with Flash Heal reduces the cast time of your next Lesser Heal, Heal, Greater Heal, or Prayer of Healing by 20% for 20 sec, stacking up to 3 times." }
entries[415996] = { ["name"] = "Engrave Gloves - Mind Sear", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Mind Sear rune:\n\nCauses an explosion of shadow magic damaging the enemy target and other nearby enemies, causing [source value] to [source value] Shadow damage every 1 sec for 6 sec to all enemies within 10 yards of the target.", ["unresolvedValues"] = true }
entries[415997] = { ["name"] = "Engrave Chest - Strength of Soul", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Strength of Soul rune:\n\nLesser Heal, Heal, Greater Heal, and Flash Heal reduce the remaining duration of Weakened Soul on targets they heal by 2 sec. In addition, targets of your Power Word: Shield will gain Rage from taking damage despite the damage being absorbed, and Righteous Fury will trigger from damage absorbed by your Power Word: Shield as if it were a heal." }
entries[416002] = { ["name"] = "Engrave Boots - Gladiator Stance", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Gladiator Stance rune:\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances." }
entries[416003] = { ["name"] = "Engrave Gloves - Single-Minded Fury", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Single-Minded Fury rune:\n\nWhile dual-wielding, your movement speed is increased by 10% and you gain 3% attack speed each time your melee auto-attack strikes the same target as your previous auto-attack, stacking up to 5 times. Lasts 10 sec or until your auto-attack strikes a different target." }
entries[416004] = { ["name"] = "Engrave Belt - Blood Surge", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Blood Surge rune:\n\nHeroic Strike, Bloodthirst, and Whirlwind have a 30% chance to make your next Slam within 15 sec instant, strike with both melee weapons, and cost no Rage." }
entries[416005] = { ["name"] = "Engrave Belt - Precise Timing", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Precision Timing rune:\n\nSlam is now instant but has a 6 sec cooldown." }
entries[416008] = { ["name"] = "Engrave Pants - Everlasting Affliction", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Everlasting Affliction rune:\n\nEach time your Drain Life, Drain Soul, or Shadowbolt spell deals damage, your Corruption on the target is refreshed to its maximum duration." }
entries[416009] = { ["name"] = "Engrave Chest - Demonic Tactics", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Demonic Tactics rune:\n\nIncreases the critical strike chance of all attacks for you and your summoned Demon by 10% while the Demon is active." }
entries[416014] = { ["name"] = "Engrave Boots - Demonic Knowledge", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Demonic Knowledge rune:\n\nIncreases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." }
entries[416015] = { ["name"] = "Engrave Bracers - Incinerate", ["text"] = "3 sec cast\nRequires Bracers\nEngrave your bracers with the Incinerate rune:\n\nDeals 100 to 114 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate." }
entries[416017] = { ["name"] = "Engrave Boots - Dance of the Wicked", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Dance of the Wicked rune:\n\nYou and your demon pet gain dodge chance equal to 100% of your spell critical strike chance each time you deal a critical strike to an enemy, and also both regain 2% of maximum mana." }
entries[416028] = { ["name"] = "Engrave Boots - Sacred Shield", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Sacred Shield rune:\n\nEach time the target takes damage they gain a Sacred Shield, absorbing [source value] damage and increasing the Paladin's chance to critically hit with Flash of Light by 50% for up to 6 sec. In addition, causes your Flash of Light to heal targets with Sacred Shield for an additional 100% over 12 sec. They cannot gain this effect more than once every 6 sec. Lasts 1 min. This spell cannot be on more than one target at any one time.", ["unresolvedValues"] = true }
entries[416031] = { ["name"] = "Engrave Boots - The Art of War", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the The Art of War rune:\n\nIncreases all Holy damage you deal by 10%, and your melee and spell critical strikes reduce the remaining cooldown on your Exorcism spell by 2 sec." }
entries[416035] = { ["name"] = "Engrave Boots - Guarded by the Light", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Guarded by the Light rune:\n\nYou gain 5% of your maximum mana every 3 sec for 15 sec after Blocking a melee attack. This effect is cancelled by casting Flash of Light, Holy Light, or Holy Shock." }
entries[416037] = { ["name"] = "Engrave Pants - Aura Mastery", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Aura Mastery rune:" }
entries[416042] = { ["name"] = "Engrave Chest - Survival of the Fittest", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Survival of the Fittest rune:\n\nReduces the chance you'll be critically hit by melee attacks by 6% and reduces all damage taken by 10%. Damage taken reduced by an additional 10% while in Bear Form or Dire Bear Form." }
entries[416044] = { ["name"] = "Engrave Gloves - Sunfire", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Sunfire rune:\n\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec.\n\nIn addition, while in Bear Form, Cat Form, or Dire Bear Form, your Moonfire is replaced with Sunfire (Bear) or Sunfire (Cat). This spell benefits from and triggers all effects associated with Moonfire.\n\nSunfire (Bear)\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec.\n\nSunfire (Cat)\nBurns the enemy for [source value] to [source value] Nature damage and then an additional [source value] Nature damage over 12 sec. Awards 1 combo point.", ["unresolvedValues"] = true }
entries[416046] = { ["name"] = "Engrave Gloves - Skull Bash", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Skull Bash rune:\n\nCharge to a target within 13 yards and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for 2 sec. Shares a cooldown with Feral Charge." }
entries[416049] = { ["name"] = "Engrave Pants - Lacerate", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Lacerate\nrune:\n\nLacerates the enemy target, making them bleed for 50 damage over 15 sec plus 10% weapon damage per existing application of Lacerate on the target. Causes a high amount of threat. This effect stacks up to 5 times on the same target." }
entries[416050] = { ["name"] = "Engrave Chest - Living Seed", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Living Seed rune:\n\nWhen you critically heal your target with any non-periodic healing spell you plant a Living Seed on the target for 50% of the amount healed. The Living Seed will bloom the next time the target takes damage or receives non-periodic healing. Lasts 15 sec." }
entries[416051] = { ["name"] = "Engrave Bracers - Elune's Fires", ["text"] = "3 sec cast\nRequires Bracers\nEngrave your bracers with the Elune's Fires rune:\n\nSome of your spells and abilities extend the duration of your damage and healing over time effects on their target:\n\nStarfire extends Moonfire by 6 sec.\nWrath extends Sunfire by 3 sec.\nRegrowth extends Rejuvenation by 6 sec.\nShred extends Rip by 2 sec.\n\nEach effect can only be extended up to its initial duration." }
entries[416054] = { ["name"] = "Engrave Belt - Power Surge", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Power Surge rune:\n\nEach time Flame Shock deals damage, it has a 5% chance to reset the cooldown on Lava Burst and Chain Lightning and make your next Lava Burst or Chain Lightning within 10 sec instant. Each time Riptide heals, it has a 5% chance to make your next Chain Heal within 10 sec instant. Additionally, every 5 sec you gain mana equal to 15% of your Intellect." }
entries[416055] = { ["name"] = "Engrave Helm - Mental Dexterity", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Mental Dexterity rune:\n\nIncreases your Attack Power by an amount equal to 100% of your Intellect." }
entries[416057] = { ["name"] = "Engrave Chest - Healing Rain", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Healing Rain rune:\n\nSelects the area 15 yards around target player, and heals all of target player's party members within that area for [source value] every second.", ["unresolvedValues"] = true }
entries[416062] = { ["name"] = "Engrave Cloak - Coherence", ["text"] = "3 sec cast\nRequires Cloak\nEngrave your cloak with the Coherence rune:\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target." }
entries[416066] = { ["name"] = "Engrave Helm - Burn", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Burn rune:\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect." }
entries[416081] = { ["name"] = "Coherence", ["text"] = "Gain the Coherence ability:\n\nCauses your Chain heal effectiveness to only reduce by 35% per jump, and Chain Lightning effectiveness to only reduce by 20% per jump. Each also jumps to 1 additional target." }
entries[416083] = { ["name"] = "Engrave Helm - Catlike Reflexes", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Catlike Reflexes rune:\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%." }
entries[416084] = { ["name"] = "Engrave Belt - Aspect of the Viper", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Aspect of the Viper rune:\n\nThe hunter takes on the aspect of the viper, causing your ranged and melee auto attacks to regenerate mana but reducing your total damage done by 10%. In addition, you gain 10% of maximum mana every 3 sec. Mana gained is based on the speed of your weapon. Only one Aspect can be active at a time." }
entries[416085] = { ["name"] = "Engrave Helm - Lock and Load", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Lock and Load rune:\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown." }
entries[416086] = { ["name"] = "Engrave Belt - Melee Specialist", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Melee Specialist rune:\n\nYour Raptor Strike is now instant, and Mongoose Bite and Raptor Strike have a 30% chance on each attack to reset the cooldowns of Mongoose Bite and Raptor Strike." }
entries[416087] = { ["name"] = "Engrave Belt - Kill Shot", ["text"] = "3 sec cast\nRequires Belt\nEngrave your belt with the Kill Shot rune:\n\nYou attempt to finish off a wounded target, firing a ranged attack dealing 100% weapon damage plus [source value]. Kill Shot has no minimum range. Kill Shot's cooldown is reset if used on an enemy that has 20% or less health.", ["unresolvedValues"] = true }
entries[416089] = { ["name"] = "Engrave Boots - Wyvern Strike", ["text"] = "3 sec cast\nRequires Boots\nEngrave your boots with the Wyvern Strike rune:\n\nReplaces your Wyvern Sting ability with Wyvern Strike, a vicious strike that deals 140% weapon damage and causes the target to Bleed for damage over time.\n\nWyvern Strike requires you to have the Wyvern Sting talent, and replaces the Wyvern Sting abilities found in the Survival spellbook." }
entries[416090] = { ["name"] = "Engrave Helm - Rapid Killing", ["text"] = "3 sec cast\nRequires Helms\nEngrave your helm with the Rapid Killing rune:\n\nReduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%." }
entries[416091] = { ["name"] = "Engrave Pants - Sniper Training", ["text"] = "3 sec cast\nRequires Pants\nEngrave your pants with the Sniper Training rune:\n\nWhen you have not moved for the last 1 sec, you have a 20% chance to gain Sniper's Aim, stacking up to 5 times. Sniper's Aim increases the critical strike chance of your Shot abilities by 2%." }
entries[416093] = { ["name"] = "Engrave Bracers - Raptor Fury", ["text"] = "3 sec cast\nRequires Bracers\nEngrave your bracers with the Raptor Fury rune:\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect." }
