entries[417135] = { ["name"] = "Gale Winds", ["text"] = "Increases the damage done by your Hurricane by 100%, it no longer has a cooldown, and its mana cost is reduced by 60%." }
entries[417141] = { ["name"] = "Berserk", ["text"] = "Instant 3 min cooldown\nRequires Cat Form, Bear Form, Dire Bear Form\nCauses your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec." }
entries[417145] = { ["name"] = "Gore", ["text"] = "Striking a target with Lacerate, Swipe, or Maul has a 15% chance to reset the cooldown on Mangle (Bear) and grant 10 Rage. Striking a target with Mangle (Cat) or Shred has a 15% chance to reset the cooldown on Tiger's Fury.\n(Proc chance: 15%, 100ms cooldown)" }
