entries[417147] = { ["name"] = "Efflorescence", ["text"] = "100 yd range\nInstant 10 sec cooldown\nHeals all party or raid members within 15 yards of the selected area for [source value] every 5.2 sec for 15 sec.", ["unresolvedValues"] = true }
