entries[417157] = { ["name"] = "Starsurge", ["text"] = "30 yd range\nInstant 6 sec cooldown\nLaunch surging stellar energies that cause [source value] to [source value] Arcane damage, and increases the damage done by your next 1 Starfire cast by 80% for 15 sec.\n\nStarsurge benefits from and triggers most talents and effects that trigger or benefit from Wrath or Starfire.", ["unresolvedValues"] = true }
