entries[417440] = { ["name"] = "Thrash (Bear)", ["text"] = "10 Rage 8 yd range\nInstant 6 sec cooldown\nRequires Bear Form, Dire Bear Form\nStrikes all nearby enemies, dealing [45 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 + 0.092 * Attack Power] Bleed damage and an additional [12 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 * 5 + 0.125 * Attack Power] Bleed damage over 15 sec. When applied from Bear Form, this effect can stack up to 3 times." }
entries[417441] = { ["name"] = "Thrash (Bear)" }
entries[417448] = { ["name"] = "Thrash (Cat)", ["text"] = "40 Energy 8 yd range\nInstant\nRequires Cat Form\nStrikes all nearby enemies, dealing [60 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 + 0.104 * Attack Power] Bleed damage and an additional [40 * (9.183105 + 0.616405 * 60 + 0.028608 * 60 * 60) / 100 * 5 + 0.0661 * 5 * Attack Power] Bleed damage over 15 sec. Awards 1 combo point." }
entries[417450] = { ["name"] = "Thrash (Cat)" }
entries[417453] = { ["name"] = "Thrash (Cat)", ["text"] = "Gain several new demonic abilities: Disrupt, Demon Charge, Demonic Howl, and Infernal Strike.\n\nChoke your enemy with a surge of Shadowy energy that deals 10 damage, interrupts spellcasting, and prevents any spell in that school from being cast for 5 sec.\n\nCharge an enemy and stun it for 1 sec. Cannot be used in combat.\n\nForces all nearby enemies to focus attacks on you for 6 sec.\n\nLeap through the air and slam down on all enemies within 8 yards of the target area, causing 100 Shadow damage and Stunning them for 2 sec." }
