entries[424990] = { ["name"] = "Engrave Gloves - Main Gauche", ["text"] = "3 sec cast\nRequires Gloves\nEngrave your gloves with the Main Gauche rune:\n\nInstantly strike with your off-hand weapon for normal off-hand weapon damage and increase your chance to parry by 100% for 5 sec or until you successfully parry. For 20 sec after using Main Gauche, Sinister Strike costs 20 less Energy, deals 50% more threat, grants stacks of Rolling with the Punches, and both Sinister Strike and Eviscerate deal 50% more damage. Awards 1 combo point.\n\nMain Gauche benefits from most talents and effects that trigger from or modify Sinister Strike. Main Gauche's effect will not discount or empower Main Gauche." }
entries[424992] = { ["name"] = "Engrave Chest - Slaughter from the Shadows", ["text"] = "3 sec cast\nRequires Chest, Chest\nEngrave your chest or robe with the Slaughter from the Shadows rune:\n\nReduces the Energy cost of your Backstab and Ambush abilities by 30, and increases the damage they deal to non-player controlled targets by 60%. [ Engrave Gloves - Mutilate : Does not apply to Mutilate / Does not apply to abilities learned from other runes.]" }
entries[425012] = { ["name"] = "Poisoned Knife", ["text"] = "25 Energy 25 yd range\nInstant 6 sec cooldown\nRequires Melee Weapon\nInstantly throw your off-hand weapon to deal normal off-hand weapon damage with a 100% chance to apply the poison from your off-hand weapon to the target. Awards 1 combo point. Refunds 5 Energy per application of Deadly Poison on the target.\n\nPoisoned Knife benefits from all talents and effects that trigger from or modify Sinister Strike." }
